package com.coffeeshop.controller;import com.coffeeshop.model.ReportModels.*;import com.coffeeshop.service.ReportService;import javafx.application.Platform;import javafx.beans.property.SimpleStringProperty;import javafx.fxml.FXML;import javafx.scene.control.*;import java.time.LocalDate;import java.util.*;import java.util.concurrent.CompletableFuture;public final class ReportsController{private final ReportService service;@FXML private DatePicker fromDate,toDate;@FXML private Label orderCountLabel,grossLabel,discountLabel,taxLabel,netLabel,expenseLabel,messageLabel;@FXML private TableView<Daily>dailyTable;@FXML private TableColumn<Daily,String>dailyDateColumn,dailyOrdersColumn,dailySalesColumn;@FXML private TableView<Payment>paymentTable;@FXML private TableColumn<Payment,String>paymentMethodColumn,paymentAmountColumn;@FXML private TableView<LowStock>stockTable;@FXML private TableColumn<LowStock,String>stockCodeColumn,stockNameColumn,stockQuantityColumn,stockReorderColumn;public ReportsController(ReportService s){service=Objects.requireNonNull(s);}@FXML private void initialize(){LocalDate now=LocalDate.now();fromDate.setValue(now.withDayOfMonth(1));toDate.setValue(now);dailyDateColumn.setCellValueFactory(v->text(v.getValue().date().toString()));dailyOrdersColumn.setCellValueFactory(v->text(Long.toString(v.getValue().orders())));dailySalesColumn.setCellValueFactory(v->text(v.getValue().sales().toPlainString()));paymentMethodColumn.setCellValueFactory(v->text(v.getValue().method()));paymentAmountColumn.setCellValueFactory(v->text(v.getValue().amount().toPlainString()));stockCodeColumn.setCellValueFactory(v->text(v.getValue().code()));stockNameColumn.setCellValueFactory(v->text(v.getValue().name()));stockQuantityColumn.setCellValueFactory(v->text(v.getValue().stock()+" "+v.getValue().unit()));stockReorderColumn.setCellValueFactory(v->text(v.getValue().reorder()+" "+v.getValue().unit()));refresh();}@FXML private void refresh(){messageLabel.setText("Loading report…");CompletableFuture.supplyAsync(()->service.report(fromDate.getValue(),toDate.getValue())).whenComplete((v,e)->Platform.runLater(()->{if(e!=null){messageLabel.setText(message(e));return;}Summary s=v.summary();orderCountLabel.setText(Long.toString(s.completedOrders()));grossLabel.setText(s.grossSales().toPlainString());discountLabel.setText(s.discounts().toPlainString());taxLabel.setText(s.tax().toPlainString());netLabel.setText(s.netSales().toPlainString());expenseLabel.setText(s.expenses().toPlainString());dailyTable.getItems().setAll(v.daily());paymentTable.getItems().setAll(v.payments());stockTable.getItems().setAll(v.lowStock());messageLabel.setText(v.daily().isEmpty()?"No completed sales in the selected period.":"");}));}private static SimpleStringProperty text(String s){return new SimpleStringProperty(s);}private static String message(Throwable e){Throwable x=e;while(x.getCause()!=null)x=x.getCause();return x instanceof IllegalArgumentException?x.getMessage():"Unable to load report data.";}}
